import { authService } from './auth-service.js';
import { config } from './config.js';
export const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
export const icon = name => ({ arrow: '↗', right: '→', play: '▷', chevron: '⌄' })[name] || name;
export const button = (label, href, variant = 'primary', extra = '') => `<a class="button button--${variant}" href="${href}" ${extra}>${label}</a>`;
export const brand = (variant = 'default') => `<a href="#/" class="brand${variant === 'image' ? ' brand--image' : ''}" aria-label="${config.name} home">${variant === 'image' ? `<img src="${config.logo}" alt="${config.name}" width="2048" height="768">` : `<span class="brand-symbol" aria-hidden="true">♜</span><span>${config.name}<small>WRATH OF THE LICH KING</small></span>`}</a>`;
const accountMenu = location => `<div class="account-menu account-menu--${location}" data-account-menu><button class="account-menu-toggle" type="button" aria-expanded="false" aria-controls="account-options-${location}" data-account-toggle>My profile <span aria-hidden="true">⌄</span></button><div class="account-menu-panel" id="account-options-${location}" hidden><a href="#/profile">View profile</a><button type="button" data-sign-out>Sign out</button></div></div>`;
export function header(page) {
  const links = [['Home', ''], ['News', 'news'], ['Server', 'server'], ['Rankings', 'rankings'], [authService.state.account ? 'My profile' : 'Account', 'account']];
  return `<header class="site-header"><svg class="nav-edge-glow" aria-hidden="true" focusable="false"><defs>${['left', 'right'].map(side => `<linearGradient id="nav-glow-${side}" gradientUnits="userSpaceOnUse" data-glow-gradient="${side}"><stop offset="0" stop-opacity="0"/><stop offset=".15" stop-opacity=".04"/><stop offset=".35" stop-opacity=".3"/><stop offset=".55" stop-opacity=".85"/><stop offset=".75" stop-opacity=".35"/><stop offset=".9" stop-opacity=".06"/><stop offset="1" stop-opacity="0"/><animateTransform attributeName="gradientTransform" type="translate" data-glow-motion="${side}" repeatCount="indefinite" calcMode="spline" keyTimes="0;1" keySplines=".4 0 .6 1"/></linearGradient>`).join('')}</defs>${['soft', 'core'].map(layer => ['left', 'right'].map(side => `<path class="nav-edge-glow__${layer}" data-glow-side="${side}" stroke="url(#nav-glow-${side})"/>`).join('')).join('')}</svg><div class="nav-impact-shine" aria-hidden="true"></div><div class="container header-inner"><div class="header-brand">${brand('image')}</div><button class="menu-toggle" aria-label="Open navigation" aria-controls="navigation" aria-expanded="false">☰</button><nav id="navigation" aria-label="Main navigation">${links.map(([label, path]) => path === 'account' && authService.state.account ? accountMenu('mobile') : `<a href="#/${path}" ${path === 'account' ? 'class="mobile-account-link"' : ''} ${page === path ? 'aria-current="page"' : ''}>${label}</a>`).join('')}<a class="mobile-play-link" href="#/play">Play now</a></nav><div class="header-actions">${authService.state.account ? accountMenu('desktop') : '<a class="account-link" href="#/account">Account</a>'}${button('Play now', '#/play', 'ghost')}</div></div><p class="account-menu-error" data-account-error role="alert" hidden></p></header>`;
}
export const footer = () => `<footer class="site-footer"><div class="container footer-top">${brand('image')}<p>${config.description}<br>A realm worth coming home to.</p><nav aria-label="Footer"><a href="#/server">The realm</a><a href="#/rules">Realm rules</a><a href="#/account">Your account</a></nav></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} ${config.name}. An independent community project.</span><span>Not affiliated with Blizzard Entertainment.</span><span class="demo-label">Development preview · Demonstration content</span></div></footer>`;
export const backgroundMedia = () => `<div class="hero-image" aria-hidden="true"><video class="background-video" data-src="${config.backgroundVideo}" muted loop playsinline preload="none" tabindex="-1"></video></div>`;
export const pageHeader = (eyebrow, title, description, downloadScene = false) => `<section class="page-heading">${backgroundMedia()}<div class="container"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="lead">${description}</p></div></section>${downloadScene ? `<div class="download-scene-overlay" aria-hidden="true"><video class="download-video" data-src="${config.downloadVideo}" muted playsinline preload="none" tabindex="-1"></video><div class="download-scene-title"><span class="eyebrow">AETHERA</span><p>Your journey<br>begins now.</p></div></div>` : ''}`;
export const sectionHeader = (eyebrow, title, action = '') => `<div class="section-heading"><div><p class="eyebrow">${eyebrow}</p><h2>${title}</h2></div>${action}</div>`;
export const badge = text => `<span class="badge">${text}</span>`;
export const dateLabel = date => new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' }).format(new Date(date.length === 10 ? date + 'T12:00:00Z' : date));
export const newsCard = article => `<article class="news-card">${article.imageUrl ? `<a class="news-image" href="#/news/${encodeURIComponent(article.id)}" aria-label="Read ${escapeHtml(article.title)}"><img src="${escapeHtml(article.imageUrl)}" alt="${escapeHtml(article.imageAlt)}" loading="lazy"><span class="image-arrow" aria-hidden="true">↗</span></a>` : ''}<div class="news-meta">${badge(escapeHtml(article.categoryName))}<time datetime="${article.publishedAt}">${dateLabel(article.publishedAt)}</time></div><h3><a href="#/news/${encodeURIComponent(article.id)}">${escapeHtml(article.title)}</a></h3><p>${escapeHtml(article.content.slice(0, 160))}${article.content.length > 160 ? '…' : ''}</p>${authService.state.account?.role === 'admin' ? `<a class="card-edit" href="#/admin/edit/${encodeURIComponent(article.id)}">Edit article →</a>` : ''}</article>`;
export function dataTable(columns, rows, label = 'Data table') {
  return `<p class="table-mobile-hint">Swipe sideways in the table to see all columns.</p><div class="table-scroll" tabindex="0" role="region" aria-label="${escapeHtml(label)}"><table><thead><tr>${columns.map(column => '<th scope="col">' + escapeHtml(column) + '</th>').join('')}</tr></thead><tbody>${rows.length ? rows.map(row => '<tr>' + row.map((cell, index) => '<td' + (label === 'Rankings table' ? (index === 0 ? ' class="rank"' : index === 1 ? ' class="player-name"' : '') : '') + '>' + cell + '</td>').join('') + '</tr>').join('') : '<tr><td colspan="' + columns.length + '" class="empty-state">No results.</td></tr>'}</tbody></table></div>`;
}
export const featureCard = feature => `<article class="feature-card"><span class="feature-icon" aria-hidden="true">${feature.icon}</span><p class="eyebrow">${feature.label}</p><h3>${feature.title}</h3><p>${feature.text}</p></article>`;
export const notice = text => `<div class="notice"><span aria-hidden="true">ⓘ</span><p>${text}</p></div>`;
export function table(columns, rows) {
  return dataTable(columns, rows.map((row, index) => [String(index + 1).padStart(2, '0'), ...row.map(escapeHtml)]), 'Rankings table');
}

export const sectionCue = (direction = 'next') => `<button class="section-scroll-cue${direction === 'top' ? ' section-scroll-cue--top' : ''}" type="button" ${direction === 'top' ? 'data-section-top aria-label="Back to top"' : 'data-section-next aria-label="Next section"'}><svg width="64" height="34" viewBox="0 0 64 34" fill="none" aria-hidden="true"><path d="M3 4L32 16L61 4M3 17L32 29L61 17" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/></svg>${direction === 'top' ? '<span>Back to top</span>' : ''}</button>`;
